from pathlib import Path
import json
p=Path('training/v10');r=json.loads((p/'results.json').read_text());labels={'base':'保持不变','ordinary':'继续普通训练','mixed':'普通＋关键阶段训练'}
lines=['# V10：继续查表强化学习的对照实验','','## 设计','','使用与 V8/V9 相同的冻结基线（V6 普通继续训练控制模型），并非网页默认 V4 权重。两组均直接更新原查表模型，不增加网络、不改变推理结构。各训练三个种子，每个模型 120 秒 CPU，最后一局结束后停止，固定使用最终权重。训练目标仍为未来分数，沿用两步行为策略与 TD(lambda)，达到 1536 后的权重保持冻结。','','关键阶段池来自另行采集的 128 局，其中 127 局达到 768，各取首次出现 768 的状态。混合组约 25% 对局从池中开始、75% 正常开局；普通组全部正常开局。恢复时重洗未发出的牌序。池采集是额外的一次性准备开销，不计入每模型 120 秒训练预算。训练 CPU 相同不代表更新次数或对局数相同。','','评估每模型512局，七个模型共3584次运行。所有模型使用同一批512个新开局种子和原 MCTS，每步1毫秒CPU软预算，合出1536或死亡即停。','','## 合出1536的成功率','','| 方案 | 种子1 | 种子2 | 种子3 | 平均成功率 | 每步模拟次数 |','|---|---:|---:|---:|---:|---:|']
for a,d in r['arms'].items():
 counts=[f'{x}/512' for x in d['wins']]+['—']*(3-len(d['wins']));lines.append(f"| {labels[a]} | {' | '.join(counts)} | {d['meanPercent']:.2f}% | {d['simulationsPerMove']:.1f} |")
lines+=['', '**结论：未发现可靠提升，网页保持现有 AI。** 普通继续训练平均95.05%，低于不训练的95.90%；混合组95.96%，仅比不训练高0.065个百分点，其探索性95%区间为[-1.93,+2.06]个百分点。混合组比普通组高0.91个百分点，但预定检验未通过，不能认定关键阶段训练有效。', '', '三组每步平均CPU均约1.008毫秒，平均模拟次数约596、602、603，未观察到V9那样的推理开销增加。训练结构不变，但这并不能证明唯一剩余问题是模型容量；本轮没有单独检验学习率、分数目标与成功目标的差异、采样池覆盖或训练时长。', '', '解释应限定为：这一训练预算、学习率和关键局面混合方案没有带来可确认收益，不意味着继续强化学习永远无法提升。', '', '## 预先指定的比较','','| 比较 | 差值（百分点） | 95%区间 | Holm校正p |','|---|---:|---:|---:|']
for k,label in [('ordinaryMinusBase','普通继续训练 − 不训练'),('mixedMinusOrdinary','混合训练 − 普通训练')]:
 d=r['contrasts'][k];lo,hi=d['CI95PP'];lines.append(f"| {label} | {d['differencePP']:+.2f} | [{lo:+.2f}, {hi:+.2f}] | {d['holmP']:.4f} |")
lines+=['','先在每个开局内对三个训练模型平均，再计算成对差异；区间条件于本次三个训练种子。不能把重复使用的开局当作1536个独立样本，也不能用这次测试选择最佳训练种子。','','## 实际训练量','','| 模型 | CPU秒 | 对局数 | 关键局面开局数 | 行动步数 |','|---|---:|---:|---:|---:|']
for n,t in r['training'].items():lines.append(f"| {n} | {t['cpuSeconds']:.2f} | {t['episodes']} | {t['resumed']} | {t['steps']} |")
lines+=['','## 限制','','- 等时间搜索受机器速度影响；来牌随机源与搜索分离，但策略分歧后同种子不代表相同后续局面。','- 每步预算是软预算，并非硬实时；实际计算时间和超时次数见results.json。','- 此实验只能评价给定训练时长、学习率和25%混合比例，不能证明继续强化学习永远没有用，也不能证明查表表示达到上限。','- 关键池只有127个不同局面，重复采样可能限制泛化；没有测试其他采样比例或更大的池。','- 没有测量6144成功率或浏览器表现。网页保持现有版本。','','## 可复现材料','','`training/v10/` 包含训练程序、协议、关键局面池、六份压缩模型、训练日志、权重哈希、3584局完整结果以及分析脚本。所有候选已验证前期权重确实变化、1536以上阶段字节不变、没有训练对局被截断。复现命令见README.md。']
Path('RL-V10-CONTINUATION.md').write_text('\n'.join(lines)+'\n')
